57	/**
58	 * Enforce the admin-configured per-user server cap (`max_servers_per_user`,
59	 * default 10; 0 = unlimited). Counts every server the user owns that isn't being
60	 * torn down (DELETING). Returns an error message when the cap is reached, else
61	 * null.
62	 *
63	 * Lives in this PLAIN module rather than lib/actions.ts (a `"use server"` file)
64	 * for the same reason `gameOrderGate` lives in lib/game-order.ts: it takes an
65	 * already-resolved `userId` and does no session check of its own, so exporting
66	 * it from a Server Actions file would let a stranger probe any account's server
67	 * count with no authentication — exactly the class of bug
68	 * test/auth-lockouts.test.ts's "HAZARD" suite exists to catch. `payAndDeploy`
69	 * (lib/actions.ts) and the PayPal/Coinbase VPS-order action
70	 * (lib/actions-payment-providers.ts) both call this AFTER their own
71	 * `requireUser()`.
72	 */
73	export async function serverLimitError(userId: string): Promise<string | null> {
74	  const cap = await getSettingInt("max_servers_per_user", 10);
75	  if (cap <= 0) return null; // 0 (or negative) = unlimited
76	  const owned = await db.server.count({ where: { userId, status: { notIn: ["DELETING"] } } });
77	  if (owned >= cap) {
78	    return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}. Delete one or contact support to raise the cap.`;
79	  }
80	  return null;
81	}
