136	/**
137	 * The price an order was SOLD at: the total, and the promo rate that produced it.
138	 * Fixed ONCE — before any money moves — and carried to the moment it is charged.
139	 *
140	 * REAL INCIDENT (2026-07-26 customer-journey rehearsal, H2). The card-paid deploy
141	 * path quoted a total, charged the CARD its share of that total at Stripe, and
142	 * then — on the confirm redirect, minutes or hours later — re-ran `orderQuote`
143	 * and debited whatever came back. That re-run includes `currentPromo(new Date())`,
144	 * and lib/promotions.ts always has an active sale that rotates by calendar date,
145	 * so a rotation between "customer clicked Deploy" and "customer came back from
146	 * Stripe" re-priced the order AFTER the card had cleared and took the difference
147	 * out of the wallet with no new consent. With no balance to take it from, the
148	 * payment was captured and no server was created.
149	 *
150	 * `lib/resize.ts` and `lib/disk-expand.ts` already carried the amount through
151	 * Stripe metadata for exactly this reason; the order path was the one that
152	 * re-derived it. Same rule as lib/renewal-quote.ts and lib/proration.ts: a figure
153	 * the customer was shown is not recomputed later, it is carried.
154	 *
155	 * `promoPercent` and `promoName` travel WITH the total because they are not
156	 * decoration. `Server.termPromoPercent` records the rate a term was actually sold
157	 * at (every later proration prices against it), and the promo name is the ledger
158	 * and invoice text the customer reads. Honouring a 30%-off price while stamping
159	 * today's 15% would hand every later proration the wrong basis and print a
160	 * discount on the invoice that does not match the money taken.
161	 */
162	export type OrderPrice = {
163	  /**
164	   * The NET (pre-tax) total the customer consented to, in cents. Its meaning is
165	   * unchanged by Finding 1 — every promo/coupon/proration figure is computed against
166	   * this net. The amount actually CHARGED is `chargeCents + (taxCents ?? 0)`.
167	   */
168	  chargeCents: number;
169	  /** Promo rate (%) that produced it; persisted as `Server.termPromoPercent`. */
170	  promoPercent: number;
171	  /** Promo name for the ledger / invoice line, e.g. "Summer Sale". */
172	  promoName: string;
173	  /**
174	   * VAT/GST on the net (Finding 1), carried through the card round-trip so the
175	   * confirm route settles the SAME tax-inclusive total the card leg was split from
176	   * — never re-derived after the card cleared. Absent on legacy/full-price sessions,
177	   * in which case the charge path recomputes it from the owner's country (0 by
178	   * default), which can only ever undertax, the conservative direction.
179	   */
180	  taxCents?: number;
181	  taxRatePercent?: number;
182	  taxCountry?: string;
183	};
184	
185	/**
186	 * The sold price implied by a quote — the ONE place a quote becomes a price. An
187	 * optional resolved tax context stamps the VAT the card round-trip must settle.
188	 */
189	export function orderPriceOf(
190	  quote: {
191	    chargeCents: number;
192	    promo: { discountPercent: number; name: string };
193	  },
194	  tax?: { taxCents: number; ratePercent: number; country: string } | null,
195	): OrderPrice {
196	  return {
197	    chargeCents: quote.chargeCents,
198	    promoPercent: quote.promo.discountPercent,
199	    promoName: quote.promo.name,
200	    ...(tax
201	      ? { taxCents: tax.taxCents, taxRatePercent: tax.ratePercent, taxCountry: tax.country }
202	      : {}),
203	  };
204	}
