273	/**
274	 * Pick the least-committed enabled node (RAM headroom), while steering AWAY from
275	 * a node this order would push to/past the CRITICAL capacity threshold when
276	 * another node has room. Falls back to primary (any node) when every candidate is
277	 * already critical — the scheduler never REFUSES an order for a capacity warning
278	 * (that's the node-capacity alert's job, lib/node-capacity.ts); it only prefers a
279	 * roomier node when one exists. DB-only so order placement never blocks on a
280	 * Proxmox round trip.
281	 */
282	/** Validate + price an order without placing it. Throws OrderError on any problem. */
283	export async function orderQuote(intent: OrderIntent, opts?: { suppressPromo?: boolean }) {
284	  const parsed = orderSchema.safeParse(intent);
285	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
286	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
287	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
288	  // A ONE-OFF CUSTOM plan (lib/custom-plan.ts createCustomPlan, "build a custom
289	  // server") is deliberately created `active: false` — every plain
290	  // `where: { active: true }` catalog/resize-picker/marketing query in this
291	  // codebase (30+ call sites, none scoped to a single order or customer) must
292	  // never surface it as a generically pickable tile. But it must still be a
293	  // valid target for the ONE order that just built it, so `sortOrder` — the
294	  // existing marker reserved for exactly this row shape — is accepted here as an
295	  // alternative to `active`. No other code path needs this carve-out: renewals
296	  // (lib/renewal-charge.ts) never check `active` at all, and the resize-target
297	  // picker's own `where: { active: true }` query correctly keeps a custom plan
298	  // out of every OTHER customer's upgrade options with no change needed there.
299	  const planPurchasable = !!plan?.active || plan?.sortOrder === CUSTOM_PLAN_SORT_ORDER;
300	  if (!planPurchasable || !os?.active) throw new OrderError("Plan or OS not available.");
301	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
302	    throw new OrderError(
303	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
304	    );
305	  }
306	  const term = vpsTerm(Number(intent.termMonths ?? 1));
307	  // The admin-configured ANNUAL discount, resolved ONCE here and passed to
308	  // `vpsTermPriceCents` so the annual term is charged at the same rate the deploy
309	  // wizard displayed and every renewal will bill. Ignored for non-annual terms.
310	  const annualPct = await annualDiscountPct();
311	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
312	
313	  // Extra root disk, priced per GB/month and multiplied over the term exactly
314	  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
315	  // promo — the customer pays the same $/GB whichever term they pick, and renews
316	  // at the same rate). Growth is one-way: this is permanent for the server.
317	  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
318	  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
319	  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
320	  const extraDiskCents = extraDiskMonthlyCents * term.months;
321	  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
322	    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
323	  }
324	
325	  // Paid backup RETENTION tier, priced per month and multiplied over the term
326	  // exactly like the extra-disk add-on (NOT promo-discounted — the customer pays
327	  // the same $/mo whichever term or promo, and renews at the same rate through
328	  // renewalCharge). Only PLUS is paid; FREE (the included tier) is $0.
329	  const backupTier = normalizeBackupTier(intent.backupTier);
330	  const backupMonthlyCents =
331	    backupTier === "FREE" ? 0 : backupTierMonthlyCents(backupTier, await backupPlusMonthlyCents());
332	  const backupCents = backupMonthlyCents * term.months;
333	
334	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
335	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
336	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
337	  // real renewal price and this discounted value is the real first-term price.
338	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
339	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
340	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months, annualPct);
341	
342	  // LOW intro price → RENEWS at regular. A per-plan `introPriceCents` (set by an
343	  // admin) makes the FIRST term cheaper and leaves every renewal at the regular
344	  // `priceCents` — renewal code never reads the intro column, so renewal === regular
345	  // by construction (lib/renewal-charge.ts). Modelled as a first-term REDUCTION of
346	  // the regular term total (not a second price), so the regular term stays the one
347	  // basis renewals bill and proration prices against. `introDiscountCents` is 0 for
348	  // every plan without an intro price, so the whole VPS flow below is unchanged for
349	  // them. VPS never carries the first-month-free promo (`firstMonthFreeAppliesTo`),
350	  // so intro and FMF never stack here.
351	  const introMonthlyCents = planIntroMonthlyCents(plan);
352	  const introTermMonths = planIntroTermMonths(plan);
353	  const introDiscountCents = introFirstTermDiscountCents(
354	    plan.priceCents,
355	    introMonthlyCents,
356	    term.months,
357	    introTermMonths,
358	    annualPct,
359	  );
360	  // The plan-portion cash the FIRST term is sold at, intro applied. Renewals ignore it.
361	  const introFirstTermPlanCents = Math.max(0, regularPlanCents - introDiscountCents);
362	  // The rate this first term is sold at (percent off the regular term total) — stamped
363	  // on Server.termPromoPercent below via the promo object so proration/refunds price
364	  // against it exactly like a seasonal promo.
365	  const introPercent = introSoldPercent(regularPlanCents, introDiscountCents);
366	  const introRenewalMonthly = plan.priceCents; // what the "then $X/mo" copy quotes
367	  // When a plan has an intro price we present it THROUGH the same `promo` channel the
368	  // seasonal-sale plumbing uses (name + percent travel on OrderPrice and stamp
369	  // termPromoPercent). `firstMonthFree: false` keeps it out of the one-month-free
370	  // redemption machinery — an intro price has no per-account cap; it is simply this
371	  // plan's first-term price.
372	  const promo =
373	    introDiscountCents > 0
374	      ? {
375	          id: "intro-price",
376	          name: `Intro price — renews at $${(introRenewalMonthly / 100).toFixed(2)}/mo`,
377	          label: "Intro price",
378	          discountPercent: introPercent,
379	          firstMonthFree: false,
380	        }
381	      : currentPromo(new Date());
382	  // The promo is now MANAGED: the owner can switch it off, and every claim is
383	  // capped 1/account + 1/IP (lib/promo-redemption.ts). When the toggle is off the
384	  // quote shows — and placeOrder charges — the full price, so display === charged
385	  // on the disabled path. When it is on, the quote shows the first-month-free
386	  // price and the atomic claim in placeOrder's tx is the final arbiter of whether
387	  // the credit is actually granted (a lost race there is charged full).
388	  // `suppressPromo` prices this quote at FULL price even when the promo is on —
389	  // the card path uses it to re-quote for a customer who has already redeemed
390	  // (per-account/IP), so their Stripe leg and stamped total are full, not free.
391	  // The first-month-free promo is scoped to Shared Web Hosting only — VPS always
392	  // bills full. `firstMonthFreeAppliesTo("VPS")` is false, so promoEnabled is
393	  // false here and planFirstTermCents falls through to the regular term total.
394	  const promoEnabled =
395	    firstMonthFreeAppliesTo("VPS") && !opts?.suppressPromo && (await firstMonthFreeEnabled());
396	  // First-month-free must credit exactly ONE MONTH — not zero a multi-month term.
397	  // A naive promoPriceCents(termTotal) at 100% off would give a 36-month term 3
398	  // YEARS free. So we subtract one month of the plan's rate from the term total.
399	  // For a 1-month term this lands at $0 (genuinely first month free); for a 12/24/
400	  // 36-month term the customer pays the term minus one month. Renewals bill the
401	  // full vpsTermPriceCents unchanged (worker/billing.ts) — displayed === charged.
402	  const planFirstTermCents =
403	    promoEnabled && promo.firstMonthFree
404	      ? Math.max(0, regularPlanCents - plan.priceCents)
405	      : regularPlanCents;
406	  // The one-month credit this order gets IF the atomic claim succeeds. 0 when the
407	  // promo is off. placeOrder adds it back to charge full when the claim is lost.
408	  const promoCreditCents = regularPlanCents - planFirstTermCents;
409	
410	  // Optional checkout coupon: a service-locked, term-capped discount on the PLAN
411	  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
412	  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
413	  // so the deploy preview can show it; the redemption itself (count + per-user +
414	  // per-IP guards) is claimed atomically in placeOrder.
415	  let couponId: string | null = null;
416	  let couponDiscountCents = 0;
417	  let couponLabel = "";
418	  let couponError = "";
419	  let couponMaxRedemptions: number | null = null;
420	  let couponFirstTimeOnly = false;
421	  const code = (intent.couponCode ?? "").trim().toUpperCase();
422	  if (code) {
423	    if (!(await getSettingBool("coupons_enabled", true))) {
424	      couponError = "Promo codes are currently disabled.";
425	    } else {
426	      const coupon = await db.coupon.findUnique({ where: { code } });
427	      if (!coupon) {
428	        couponError = "That code isn’t valid.";
429	      } else {
430	        const verdict = couponOrderDiscountCents(
431	          {
432	            kind: coupon.kind,
433	            value: coupon.value,
434	            serviceKind: coupon.serviceKind,
435	            planSlug: coupon.planSlug,
436	            maxTermMonths: coupon.maxTermMonths,
437	            active: coupon.active,
438	            expiresAt: coupon.expiresAt,
439	            maxRedemptions: coupon.maxRedemptions,
440	            timesRedeemed: coupon.timesRedeemed,
441	            minAmountCents: coupon.minAmountCents,
442	          },
443	          {
444	            serviceKind: "VPS",
445	            planSlug: plan.slug,
446	            planMonthlyCents: plan.priceCents,
447	            termMonths: term.months,
448	            // Coupon discounts the intro-reduced plan portion, so an intro price and a
449	            // coupon cannot together drive the plan charge below zero, and a percentage
450	            // coupon is honestly "% off what you actually pay this term".
451	            planChargeCents: introFirstTermPlanCents,
452	          },
453	          new Date(),
454	        );
455	        if (verdict.ok) {
456	          couponId = coupon.id;
457	          couponDiscountCents = verdict.discountCents;
458	          couponLabel = verdict.label;
459	          couponMaxRedemptions = coupon.maxRedemptions;
460	          couponFirstTimeOnly = coupon.firstTimeOnly;
461	        } else {
462	          couponError = verdict.error;
463	        }
464	      }
465	    }
466	  }
467	
468	  const chargeCents = introFirstTermPlanCents - couponDiscountCents + ipCents + extraDiskCents + backupCents;
469	  return {
470	    plan,
471	    os,
472	    term,
473	    chargeCents,
474	    // Intro pricing (0 / null on plans without one). `introDiscountCents` is the
475	    // first-term saving already baked into `chargeCents`; `introFirstTermPlanCents`
476	    // is the plan-portion cash the first term is sold at; the monthly figures drive
477	    // the honest "$intro first term, then $regular/mo" copy on the pricing cards.
478	    introDiscountCents,
479	    introFirstTermPlanCents,
480	    introMonthlyCents,
481	    introTermMonths,
482	    introRenewalMonthly,
483	    introPercent,
484	    // The annual-discount rate this quote was priced at — snapshot onto the Server at
485	    // sale (Finding 2) so every later proration reads the SAME basis and a round trip
486	    // nets to zero even if the admin retunes `annual_discount_percent` in between.
487	    annualPct,
488	    promo,
489	    promoCreditCents,
490	    regularPlanCents,
491	    extraDiskGB,
492	    extraDiskMonthlyCents,
493	    extraDiskCents,
494	    backupTier,
