506	/**
507	 * Place an order: validate, charge the wallet (unless a free admin grant),
508	 * create the Server + PROVISION job. Returns the new server id. Does NOT
509	 * redirect. Callers must ensure funds exist (or pass free) — this still
510	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
511	 *
512	 * `sold` overrides the recomputed price with the one the order was actually SOLD
513	 * at — the card-paid path passes the figure stamped on the Checkout session
514	 * BEFORE the card was charged, so the confirm redirect settles the price the
515	 * customer consented to instead of re-pricing against whatever promo is running
516	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
517	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
518	 * quote, which it computed moments ago in the same request. See OrderPrice.
519	 */
520	/**
521	 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
522	 * any failure so nothing partial survives. Kept separate from the order tx so a
523	 * wallet order can surface the failure before any money moves, and a card order
524	 * (already paid) can swallow it without stranding the paid provision.
525	 *
526	 * Guards, all enforced here: first-time-only (no prior paid server), the
527	 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
528	 * (the two @@unique constraints on CouponRedemption).
529	 */
530	async function claimOrderCoupon(opts: {
531	  couponId: string;
532	  maxRedemptions: number | null;
533	  firstTimeOnly: boolean;
534	  userId: string;
535	  ipHash: string | null;
536	  amountCents: number;
537	}): Promise<void> {
538	  await db.$transaction(async (tx) => {
539	    // Self-heal first: a dead hold from THIS customer's own abandoned card checkout must
540	    // not stand between them and this coupon on a fresh (wallet) order — and its global
541	    // slot is handed back here too. Guarded to expired RESERVED rows (lib/coupon-redemption.ts).
542	    await releaseExpiredCouponHoldsFor(tx, opts.couponId, opts.userId, opts.ipHash);
543	    if (opts.firstTimeOnly) {
544	      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
545	      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
546	    }
547	    // Atomic conditional increment — the only thing between the last free slot and
548	    // an over-redemption when two orders race for it.
549	    const claim = await tx.coupon.updateMany({
550	      where:
551	        opts.maxRedemptions === null
552	          ? { id: opts.couponId, active: true }
553	          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
554	      data: { timesRedeemed: { increment: 1 } },
555	    });
556	    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
557	    try {
558	      await tx.couponRedemption.create({
559	        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
560	      });
561	    } catch {
562	      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
563	      // this person. Throwing rolls back the increment above with it.
564	      throw new OrderError("You’ve already used this code.");
565	    }
566	  });
567	}
