569	/**
570	 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
571	 *
572	 * The card leg discounts `cardCents` up front and only settles the redemption
573	 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
574	 * paid provision is never stranded. Without this pre-check, a customer who has
575	 * already used a one-per-person code (or isn't first-time) still gets the
576	 * discounted card charge and the swallow hides it. So before we send them to
577	 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
578	 * plain reads; if any fails the caller re-quotes at full price. This is advisory
579	 * (a race could still lose the atomic claim at settle time — that path stays
580	 * swallowed by design), but it closes the everyday bypass.
581	 */
582	export async function orderCouponClaimable(opts: {
583	  couponId: string;
584	  firstTimeOnly: boolean;
585	  maxRedemptions: number | null;
586	  userId: string;
587	  ipHash: string | null;
588	}): Promise<{ ok: true } | { ok: false; error: string }> {
589	  if (opts.firstTimeOnly) {
590	    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
591	    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
592	  }
593	  const byUser = await db.couponRedemption.findUnique({
594	    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
595	  });
596	  if (byUser) return { ok: false, error: "You’ve already used this code." };
597	  if (opts.ipHash) {
598	    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
599	    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
600	  }
601	  if (opts.maxRedemptions !== null) {
602	    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
603	    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
604	  }
605	  return { ok: true };
606	}
