608	export async function placeOrder(
609	  user: User,
610	  intent: OrderIntent,
611	  sold?: OrderPrice | null,
612	  opts?: {
613	    ipHash?: string | null;
614	    campaign?: string;
615	    promoReservationToken?: string | null;
616	    couponReservationToken?: string | null;
617	  },
618	): Promise<string> {
