621	  // Everything below bills off THESE three, never off `quote.chargeCents` /
622	  // `promo` directly: when a sold price is present it is the whole truth about
623	  // what this order costs and what rate it was sold at.
624	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
625	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
626	  const promoName = sold?.promoName || promo.name;
627	
628	  // Managed first-month-free — how this order settles the credit depends on the path:
629	  //   WALLET path (no `sold`): the credit rides on the fresh quote (promoCreditCents
630	  //     > 0), and we contend for it with an atomic INSERT inside the charge tx below.
631	  //   CARD/Stripe path (`sold` present): the credit was already RESERVED before the
632	  //     card was charged, and its hold token travels in `opts.promoReservationToken`.
633	  //     We CONFIRM that hold (never a fresh contended INSERT) — that is what closes
634	  //     the double-claim race. No token => this order was sold at FULL price, so there
635	  //     is nothing to grant. We deliberately do NOT infer the credit from
636	  //     `sold.promoPercent` (currentPromo always stamps 100, even on a full-price VPS
637	  //     order), which would record a redemption for a purchase that never got one.
638	  const walletPromoApplied = !sold && promoCreditCents > 0;
639	  const cardPromoToken = sold ? opts?.promoReservationToken ?? null : null;
640	  // Note the intro discount on the billing document (first term only; renews full) —
641	  // ONLY when this specific order actually earned the credit (real customer report:
642	  // a full-price $8.88 VPS invoice read "First month free · 100% off first term",
643	  // because `promo.discountPercent` is a raw, ALWAYS-100 constant — see the comment
644	  // above — and this used to gate on that instead of on whether the credit was
645	  // actually granted to THIS order, same signal walletPromoApplied/cardPromoToken
646	  // already use to decide whether to grant it).
647	  const promoNote = walletPromoApplied || cardPromoToken ? ` · ${promoName} ${promoPercent}% off first term` : "";
648	  // The checkout coupon settles the same two ways:
649	  //   WALLET path (no `sold`): atomic claim in its OWN tx below (claimOrderCoupon), which
650	  //     throws and surfaces before any money moves if the last slot just went.
651	  //   CARD/Stripe path (`sold`): the coupon was RESERVED before the card was charged and
652	  //     its hold token travels in `opts.couponReservationToken`. We CONFIRM that hold
653	  //     inside the charge tx (never a fresh contended claim — that would double-count the
654	  //     global cap and collide on the per-person unique). No token => full-price order.
655	  const cardCouponToken = sold ? opts?.couponReservationToken ?? null : null;
