665	  } else {
666	    const n = await scheduleNode(plan.ramMB);
667	    nodeId = n?.id ?? null;
668	  }
669	
670	  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
671	  const diskCap = await diskCapacityCheck(nodeId, effectiveDiskGB(plan.diskGB, extraDiskGB));
672	  if (!diskCap.ok) throw new OrderError(diskCap.reason);
673	
674	  const addons = {
675	    malwareScanner: !!intent.addonMalware,
676	    dailyBackup: !!intent.addonBackup,
677	    docker: !!intent.addonDocker,
678	  };
