897	        // Cast: the symlinked prod Prisma client's types predate `annualDiscountPct`
898	        // (regenerated at deploy — identical at runtime then; see lib/promo-redemption.ts).
899	        data: {
900	          name: intent.hostname,
901	          hostname: intent.hostname,
902	          userId: user.id,
903	          planId: plan.id,
904	          osTemplateId: os.id,
905	          partnerSource: intent.partnerSource ?? null,
906	          nodeId,
907	          addons,
908	          // The wizard sells "Daily auto-backups" ("Nightly snapshots to separate
909	          // storage for easy restore") and re-confirms it on the Review step, but
910	          // `addons.dailyBackup` was write-only: the worker declares the key and
911	          // never reads it, and the REAL scheduler (worker/backup-schedule.ts)
912	          // keys off `autoBackup` + `backupIntervalHours`, whose only writer was
913	          // the Backups tab. Nothing bridged the two, so EVERY server in the live
914	          // DB carried `addons.dailyBackup` with `autoBackup: false` and no backup
915	          // job was ever enqueued. A customer would discover the safety net they
916	          // were promised did not exist at the moment they needed it. Bridge it
917	          // here, at the point of sale. A PAID backup tier (PLUS) implies backups
918	          // are on regardless of the free "Daily auto-backups" toggle — you cannot
919	          // sell retention on a schedule that never runs. `backupTier`/`backupKeep`
920	          // are the columns the retention lever (worker/index.ts backupCreate)
921	          // reads; keep null on FREE so it falls back to the tier default.
922	          autoBackup: !!intent.addonBackup || backupTier !== "FREE",
923	          backupIntervalHours:
924	            !!intent.addonBackup || backupTier !== "FREE" ? backupTierSpec(backupTier).intervalHours : null,
925	          backupTier,
926	          backupKeep: backupTier === "FREE" ? null : backupTierSpec(backupTier).keep,
927	          termMonths: term.months,
928	          // THE RATE THIS TERM WAS SOLD AT, recorded at the moment of sale. Every
929	          // later proration prices the plan delta against this number instead of
930	          // whatever promo happens to be running when the customer clicks resize
931	          // (lib/proration.ts) — otherwise the customer chooses the rate for each
932	          // half of a round trip by choosing the date, and pockets the spread.
933	          // `chargeCents` above is literally promoPriceCents(regular, promo), so
934	          // this scalar and the cash collected describe the same transaction.
935	          // A free admin grant recorded as 100: nothing was paid for these months,
936	          // so nothing may ever prorate out of them.
937	          //
938	          // `effectivePromoPercent` — not `promo.discountPercent` — because a
939	          // card-paid order settles the rate it was SOLD at (see OrderPrice), which
940	          // may no longer be the promo running now, AND because a wallet order that
941	          // lost the first-month-free claim paid FULL price (0% off): recording 100
942	          // there would let a later downgrade prorate out a discount nobody was
943	          // charged. Recording today's rate against a price collected under a
944	          // different one is exactly the drift this column exists to prevent.
945	          termPromoPercent: effectivePromoPercent,
946	          // The ANNUAL discount rate in force when this term was sold, frozen here so
947	          // every later proration prices against it and an up-then-down round trip nets
948	          // to zero even if the admin retunes `annual_discount_percent` in between
949	          // (Finding 2). Ignored for non-annual terms by `termDiscountPct`; a free admin
950	          // grant never prorates, so its value is inert. `quote.annualPct` is the very
951	          // rate `regularPlanCents`/`chargeCents` above were priced at.
952	          annualDiscountPct: quote.annualPct,
953	          // The plan-portion cash actually collected for this term, net of promo AND
954	          // coupon AND the intro discount, EXCLUDING recurring add-ons — the
955	          // authoritative refund basis (see Server.refundableTermCents).
956	          // `regularPlanCents` is the full term list; subtract the promo credit ONLY if
957	          // the claim held (a lost wallet claim paid full, `soldFull`), always subtract
958	          // the coupon, and always subtract the intro discount (both reduced cash but
959	          // not `termPromoPercent`; the intro discount is baked into `chargeCents`).
960	          // Clamped ≥ 0. A free admin grant collected nothing, so 0.
961	          refundableTermCents: freeRequested
962	            ? 0
963	            : Math.max(
964	                0,
965	                quote.regularPlanCents -
966	                  (soldFull ? 0 : promoCreditCents) -
967	                  quote.couponDiscountCents -
968	                  quote.introDiscountCents,
969	              ),
970	          // Persisted BEFORE the PROVISION job runs, so the worker clones the VM
971	          // and resizes scsi0 straight to plan.diskGB + extraDiskGB — the server is
972	          // born at its full size, with no separate expansion job.
973	          extraDiskGB,
974	          wantsDedicatedIp: !!intent.dedicatedIp,
975	          isFree: freeRequested,
976	          expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
977	        } as Prisma.ServerUncheckedCreateInput,
978	      });
979	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
980	      // Anchor the redemption to the created server so the renewal worker can flip
981	      // `renewed` when this customer bills their second term, and stamp the true
982	      // first-term charge. Same tx, so it commits (or rolls back) with the order.
983	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, s.id, debitCents);
984	      return s;
985	    });
986	  } catch (e) {
987	    if (e instanceof InsufficientBalanceError) throw new OrderError("Insufficient balance.");
988	    throw e;
989	  }
990	
991	  await db.auditLog.create({
992	    data: {
993	      userId: user.id,
994	      action: "server.order",
995	      detail: `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo extraDisk=${extraDiskGB}GB free=${freeRequested}`,
996	    },
997	  });
998	  if (!freeRequested) {
999	    try {
1000	      await maybeRewardReferral(user.id);
1001	    } catch {
1002	      /* non-fatal */
1003	    }
1004	    // Soft monthly-budget alert (Finding 3): fire once when this charge tips spend
1005	    // over the customer's budget. Best-effort — never fails an order.
1006	    await maybeAlertBudget(user.id);
1007	    // KOL/Agency partner commission: if this customer is attached to a partner,
1008	    // accrue commission on the PAID order invoice now (idempotent; the background
1009	    // sweep would otherwise catch it within minutes). Best-effort by design.
1010	    await accrueRecentCommissionsForCustomer(user.id);
1011	  }
1012	  // Deploy-funnel COMPLETION — the authoritative, server-side bottom of the funnel.
1013	  // This is the ONE place a VPS order is definitively created & paid: both the wallet
1014	  // path (lib/actions.ts payAndDeploy) and the card path (lib/fulfil-checkout.ts, run
1015	  // by the Stripe webhook or the success redirect) reach it, so recording here counts
1016	  // every completed VPS deploy exactly once, with a reliable `userId`. The step index
1017	  // orders it at the tail (after Review/Payment); the completion is a terminal event,
1018	  // not a wizard step, so it drives the completed counts rather than rendering a row.
1019	  // Best-effort AND double-guarded: `recordDeployFunnelComplete` already swallows every
1020	  // failure, and the extra catch guarantees analytics can never disturb the money path.
1021	  try {
1022	    await recordDeployFunnelComplete({ product: "vps", step: "Complete", stepIndex: 8, userId: user.id });
1023	  } catch {
1024	    /* never let funnel bookkeeping affect a completed order */
1025	  }
1026	  // Email the paid ORDER invoice with its PDF attached. Best-effort AND post-commit:
1027	  // the money has already moved, so a mail failure must NEVER surface as an order
1028	  // failure. Fires exactly once per order (single commit) and covers BOTH the wallet
1029	  // path (lib/actions.ts) and the card path (lib/fulfil-checkout.ts) because both go
1030	  // through this one placeOrder. This is the invoice DOCUMENT — deliberately
1031	  // `invoiceNew` (subject "Invoice #… — $… due"), not `receipt`, so it does not
1032	  // collide with the separate "Payment received" wallet/card top-up receipt a card
1033	  // order already gets from lib/stripe.ts. Passing `invoiceId` + the `invoice_new`
1034	  // template makes lib/mailer.ts auto-attach the rendered PDF. `orderInvoice` is null
1035	  // for free admin grants (no invoice created), so those email nothing.
1036	  // Read via the declared union — the value is assigned inside the $transaction
1037	  // callback, which TS control-flow analysis does not track, so a direct read would
1038	  // narrow to `null`.
1039	  const invForEmail = orderInvoice as { id: string; number: number; amountCents: number; description: string } | null;
1040	  if (invForEmail) {
1041	    try {
1042	      const { sendMail, emails } = await import("./mailer");
1043	      const branding = await invoiceBranding();
1044	      const tpl = emails.invoiceNew(
1045	        {
1046	          invoiceNumber: formatInvoiceNumber(invForEmail.number, branding.numberPrefix),
1047	          amount: `$${(invForEmail.amountCents / 100).toFixed(2)}`,
1048	          dueDate: new Date().toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }),
1049	          description: invForEmail.description,
1050	        },
1051	        true, // the itemised PDF is attached (invoiceId passed below)
1052	      );
1053	      await sendMail({
1054	        to: user.email,
1055	        subject: tpl.subject,
1056	        html: tpl.html,
1057	        template: tpl.template,
1058	        invoiceId: invForEmail.id,
1059	        userId: user.id,
1060	        kind: "invoice",
1061	      });
1062	    } catch {
1063	      /* invoice email is best-effort — a placed order must never fail on mail */
1064	    }
1065	  }
1066	  return server.id;
1067	}
