1	/**
2	 * Managed first-month-free promotion — the atomic redemption core.
3	 *
4	 * This mirrors lib/order.ts `claimOrderCoupon`: a conditional INSERT guarded by
5	 * two @@unique constraints (PromoRedemption `@@unique([promoId,userId])` and
6	 * `@@unique([promoId,ipHash])`) that runs INSIDE the order's charge transaction.
7	 * If the insert violates either constraint (this account OR this IP already
8	 * redeemed) it returns `{ claimed: false }` — it never throws for that case — so
9	 * the caller can charge the FULL price and still complete the order.
10	 *
11	 * THE MONEY RULE (owner will review this file personally):
12	 *   - The free-month credit is applied to an order ONLY when `claimed === true`.
13	 *   - If the claim is lost (already redeemed by account/IP) OR the promo is
14	 *     switched off via the `first_month_free_enabled` setting, the customer is
15	 *     charged the FULL price. The order still succeeds — it just isn't free.
16	 *   - The caps are FIXED at 1/account + 1/IP and are enforced ONLY by the two
17	 *     unique constraints. There is no configurable cap to drift out of sync.
18	 *
19	 * WHY A TYPED VIEW instead of `db.promoRedemption` directly: the Prisma client in
20	 * this tree is symlinked from prod and is only regenerated at deploy time, so its
21	 * types do not yet know about the new PromoRedemption model. Rather than sprinkle
22	 * `as any` across four money-critical order flows, every raw-delegate access is
23	 * contained HERE behind `promoDelegate(...)`, and the rest of the codebase calls
24	 * the strongly-typed helpers below. When the client is regenerated the runtime is
25	 * identical; only these casts become redundant.
26	 */
27	
28	import { randomUUID } from "crypto";
29	import { Prisma } from "@prisma/client";
30	import { db } from "./db";
31	import { getSettingInt } from "./settings";
32	
33	/** The single managed promo id. */
34	export const FIRST_MONTH_FREE_PROMO_ID = "first-month-free";
35	
36	/**
37	 * How many first-month-free grants a single IP may accumulate before it's capped
38	 * (admin `first_month_free_ip_limit`, default 5). This replaced a hard unique(1)-per-IP
39	 * that false-blocked NAT-sharing customers. 0 disables the IP cap entirely (per-user
40	 * only). Clamped to a sane range so a stray setting value can't block everyone or
41	 * open the floodgates.
42	 */
43	export async function firstMonthFreeIpLimit(): Promise<number> {
44	  const v = await getSettingInt("first_month_free_ip_limit", 5);
45	  return Math.min(1000, Math.max(0, Math.round(v)));
46	}
47	
48	/**
49	 * Redemption row lifecycle. A wallet-atomic flow inserts a CONSUMED grant in one
50	 * step; the card/Stripe flow first inserts a RESERVED hold (before the card is
51	 * charged) and later confirms it to CONSUMED. Both states physically occupy the two
52	 * unique slots, so a live hold blocks a second claim exactly like a grant.
53	 */
54	export const PROMO_STATE = { RESERVED: "RESERVED", CONSUMED: "CONSUMED" } as const;
55	export type PromoState = (typeof PROMO_STATE)[keyof typeof PROMO_STATE];
56	
57	/** Products the promo can be granted on (matches PromoRedemption.serviceType). */
58	export type PromoServiceType = "VPS" | "HOSTING" | "EMAIL" | "GAME";
59	
60	/** A minimal, honestly-typed shape of the row we read back. */
61	export type PromoRedemptionRow = {
62	  id: string;
63	  promoId: string;
64	  userId: string;
65	  ipHash: string | null;
66	  serviceType: string;
67	  campaign: string;
68	  orderRef: string | null;
69	  renewed: boolean;
70	  renewedAt: Date | null;
71	  chargedCents: number;
72	  state: string;
73	  reservedUntil: Date | null;
74	  reservationToken: string | null;
75	  createdAt: Date;
76	};
77	
78	/**
79	 * The subset of the PromoRedemption Prisma delegate this module uses, typed by
80	 * hand so the call sites stay type-checked even before the client is regenerated.
81	 */
82	type PromoWhere = {
83	  promoId?: string;
84	  userId?: string;
85	  ipHash?: string;
86	  orderRef?: string;
87	  renewed?: boolean;
88	  state?: string;
89	  reservationToken?: string;
90	  reservedUntil?: { lt: Date };
91	};
92	type PromoDelegate = {
93	  create(args: {
94	    data: {
95	      promoId?: string;
96	      userId: string;
97	      ipHash: string | null;
98	      serviceType: string;
99	      campaign: string;
100	      orderRef?: string | null;
101	      chargedCents: number;
102	      state?: string;
103	      reservedUntil?: Date | null;
104	      reservationToken?: string | null;
105	    };
106	    select?: { id: true };
107	  }): Promise<{ id: string }>;
108	  findUnique(args: {
109	    where: { promoId_userId: { promoId: string; userId: string } };
110	    select?: { id: true };
111	  }): Promise<{ id: string } | null>;
112	  findFirst(args: {
113	    where: PromoWhere;
114	    select?: { id: true };
115	  }): Promise<{ id: string } | null>;
116	  findMany(args?: {
117	    where?: PromoWhere;
118	    orderBy?: { createdAt: "asc" | "desc" };
119	  }): Promise<PromoRedemptionRow[]>;
120	  updateMany(args: {
121	    where: PromoWhere;
122	    data: { renewed?: boolean; renewedAt?: Date; state?: string; reservedUntil?: Date | null };
123	  }): Promise<{ count: number }>;
124	  update(args: {
125	    where: { id: string };
126	    data: { orderRef?: string | null; chargedCents?: number };
127	  }): Promise<{ id: string }>;
128	  deleteMany(args: { where: PromoWhere }): Promise<{ count: number }>;
129	  count(args?: { where?: PromoWhere }): Promise<number>;
