164	/**
165	 * Read-only pre-check: could THIS user / IP still claim the promo? Mirrors
166	 * `orderCouponClaimable` — used before the wallet balance gate so a first-time,
167	 * $0-balance customer can be quoted the free (zero) price and pass the gate,
168	 * while a repeat account/IP is quoted (and gated against) the full price. It is
169	 * advisory only; the authoritative decision is the atomic `claimFirstMonthFree`
170	 * inside the charge tx, which is the sole arbiter of whether money is discounted.
171	 */
172	export async function firstMonthFreeEligible(
173	  userId: string,
174	  ipHash: string | null,
175	): Promise<boolean> {
176	  const d = promoDelegate(db);
177	  const byUser = await d.findUnique({
178	    where: { promoId_userId: { promoId: FIRST_MONTH_FREE_PROMO_ID, userId } },
179	    select: { id: true },
180	  });
181	  if (byUser) return false;
182	  if (ipHash) {
183	    // Soft, configurable per-IP cap (was a hard unique(1) that blocked NAT-shared IPs).
184	    // Count existing grants/holds for this IP and block only once the limit is reached.
185	    const limit = await firstMonthFreeIpLimit();
186	    if (limit > 0) {
187	      const byIp = await d.count({ where: { promoId: FIRST_MONTH_FREE_PROMO_ID, ipHash } });
188	      if (byIp >= limit) return false;
189	    }
190	  }
191	  return true;
