377	/**
378	 * Backfill the created server/account/subscription id (and the final charged
379	 * amount) onto a redemption we just claimed, in the same tx. Kept off the claim
380	 * itself because the resource id is minted after the claim within the tx.
381	 */
382	export async function setPromoOrderRef(
383	  tx: Prisma.TransactionClient,
384	  redemptionId: string,
385	  orderRef: string,
386	  chargedCents: number,
387	): Promise<void> {
388	  await promoDelegate(tx).update({
389	    where: { id: redemptionId },
390	    data: { orderRef, chargedCents },
391	  });
392	}
