394	/**
395	 * Mark the promo redemption anchored to `orderRef` as RENEWED, the first time
396	 * that service bills its SECOND term. Idempotent: the `renewed: false` guard
397	 * means a repeated/racing renewal sweep matches zero rows and does nothing.
398	 * Called inside the renewal charge tx so it commits with the money.
399	 */
400	export async function markPromoRenewed(
401	  tx: Prisma.TransactionClient,
402	  orderRef: string,
403	): Promise<void> {
404	  await promoDelegate(tx).updateMany({
405	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, orderRef, renewed: false },
406	    data: { renewed: true, renewedAt: new Date() },
407	  });
408	}
