410	/** One-month credit for a flat-priced term (used by the game flow). */
411	export function firstMonthCreditCents(termPriceCents: number, termMonths: number): number {
412	  if (termMonths <= 1) return termPriceCents; // whole (single-month) term is free
413	  const oneMonth = Math.round(termPriceCents / termMonths);
414	  return Math.min(termPriceCents, oneMonth);
415	}
