1	/**
2	 * Shared types + score helper for the "vs" comparison template
3	 * (components/marketing/comparisontemplate/*). The template itself
4	 * (ComparisonTemplate.tsx) is competitor-agnostic: every live "Nxeon vs X" /
5	 * "X alternative" page supplies its own `ComparisonData` object (see the
6	 * per-competitor files in this directory, e.g. `digitalocean.ts`) and passes
7	 * it in as the `data` prop.
8	 *
9	 * Rows are grouped (pricing / specs / support / platform) exactly like the
10	 * live comparison surface (CompareTable + ComparePageLayout), and the verdict
11	 * is three-way on purpose:
12	 *
13	 *   - "win"   → a genuine Nxeon differentiator (cyan check on the Nxeon side).
14	 *   - "tie"   → an honest, even match (a neutral dash — no manufactured win).
15	 *   - "other" → the competitor is the better fit here, and we say so.
16	 *
17	 * A comparison that only ever "wins" reads as marketing and gets discounted by
18	 * readers and by AI assistants alike; crediting the competitor where they lead
19	 * is exactly what makes the wins believable. Reviews are ILLUSTRATIVE sample
20	 * content (same status as the live <Testimonials/>) — no fabricated counts, and
21	 * the real Trustpilot/HostAdvice/Google numbers come from <ReviewBadges/>.
22	 */
23	
24	export type Verdict = "win" | "tie" | "other";
25	
26	export type CompareRow = {
27	  /** The feature axis, e.g. "Automatic backups". */
28	  feature: string;
29	  /** Nxeon's value for this row. */
30	  nxeon: string;
31	  /** The competitor's value for this row. */
32	  other: string;
33	  /** "win" → Nxeon leads · "tie" → even · "other" → competitor leads. */
34	  verdict: Verdict;
35	  /** One-line, honest context shown under the feature. */
36	  note: string;
37	};
38	
39	export type CompareGroup = {
40	  /** Section label, e.g. "Pricing & terms". */
41	  label: string;
42	  rows: CompareRow[];
43	};
44	
45	export type SwitchReason = {
46	  icon: "shield" | "backup" | "support" | "bolt";
47	  title: string;
48	  body: string;
49	};
50	
51	export type MiniReview = {
52	  id: string;
53	  quote: string;
54	  name: string;
55	  meta: string;
56	};
57	
58	export type Faq = { q: string; a: string };
59	
60	/** The competitor's identity — name, logo slug and a neutral one-liner. */
61	export type CompetitorIdentity = {
62	  name: string;
63	  /** Lower-case slug → real logo at /public/logos/<slug>.svg (drop-in convention). */
64	  slug: string;
65	  /** Neutral one-liner for how the competitor positions itself — used in the header. */
66	  kind: string;
67	};
68	
69	/**
70	 * Everything ComparisonTemplate needs to render one "Nxeon vs X" page. Every
71	 * live comparison page owns one of these (see `./digitalocean.ts` etc.) built
72	 * from that page's own real, previously-published facts — no invented
73	 * competitor figures.
74	 */
75	export type ComparisonData = {
76	  competitor: CompetitorIdentity;
77	  /** The hero headline/subhead — written per-competitor, not templated. */
78	  hero: {
79	    /** Plain-text lead-in, e.g. "Same NVMe speed. " */
80	    lead: string;
81	    /** The gradient-highlighted close, e.g. "Zero babysitting." */
82	    highlight: string;
83	    /** The paragraph beneath the H1 — names the competitor's real tradeoff. */
84	    body: string;
85	  };
86	  compareGroups: CompareGroup[];
87	  switchReasons: SwitchReason[];
88	  chooseNxeon: string[];
89	  chooseOther: string[];
90	  reviews: MiniReview[];
91	  faq: Faq[];
92	  disclaimer: string;
93	};
94	
95	/**
96	 * Honest three-way scoreboard, derived from the rows so the hero can never
97	 * drift from the table — and so the competitor's genuine wins are counted,
98	 * not hidden.
99	 */
100	export function deriveScore(compareGroups: CompareGroup[]) {
101	  const rows = compareGroups.flatMap((g) => g.rows);
102	  return {
103	    nxeonWins: rows.filter((r) => r.verdict === "win").length,
104	    ties: rows.filter((r) => r.verdict === "tie").length,
105	    otherWins: rows.filter((r) => r.verdict === "other").length,
106	    total: rows.length,
107	  };
108	}
